      "ur": "الم[1]",
      "en": "Alif, Lām, Meem.[113]",
      "footnotesUr": "[1]  مُحْكَمَاتٌ سے مراد وہ آیات ہیں جن میں اوا مر ونواہی، احکام ومسائل اور قصص وحکایات ہیں جن کا مفہوم واضح اور اٹل ہے، اور ان کے سمجھنے میں کسی کو اشکال پیش نہیں آتا۔ اس کے برعکس آيَاتٌ مُتَشَابِهَاتٌ ہیں مثلاً اللہ کی ہستی، قضا وقدر کے مسائل، جنت دوزخ، ملائکہ وغیرہ یعنی ماورا عقل حقائق جن کی حقیقت سمجھنے سے عقل انسانی قاصر ہو یا ان میں ایسی تاویل کی گنجائش ہو یا کم از کم ایسا ابہام ہو جس سے عوام کو گمراہی میں ڈالنا ممکن ہو۔ اسی لئے آگے کہا جا رہا ہے کہ جن کے دلوں میں کجی ہوتی ہے وہ آیات متشابہات کے پیچھے پڑے رہتے ہیں اور ان کے ذریعے سے (فتنے) برپا کرتے ہیں۔ جیسے عیسائی ہیں۔ قرآن نےحضرت عیسیٰ (عليه السلام) کو عبداللہ اور نبی کہا ہے یہ واضح اور محکم بات ہے۔ لیکن عیسائی اسے چھوڑ کر قرآن کریم سے حضرت عیسیٰ (عليه السلام) کو روح اللہ اور کلمۃ اللہ جوکہا گیا ہے، اس سے اپنے گمراہ کن عقائد پر غلط استدلال کرتے ہیں۔ یہی حال اہل بدعت کاہے۔ قرآن کے واضح عقائد کے برعکس اہل بدعت نے جو غلط عقائد گھڑ رکھے ہیں، وہ انہی مُتَشَابِهَاتٌ کو بنیاد بناتے ہیں۔ اور بسا اوقات مُحْكَمَاتٌ کوبھی اپنے فلسفیانہ استدلال کے گورکھ دھندے سے مُتَشَابِهَاتٌ بناتے ہیں۔ أَعَاذَنَا اللهُ مِنْهم نہ ان کے برعکس صحیح العقیدہ مسلمان محکمات پرعمل کرتا ہے اورمُتَشَابِهَاتٌ کے مفہوم کو بھی (اگر اس میں اشتباہ ہو) محکمات کی روشنی میں سمجھنے کی کوشش کرتا ہے کیونکہ قرآن نے انہی کو (اصل کتاب) قرار دیا ہے۔ جس سے وہ فتنے سے بھی محفوظ رہتا ہے اور عقائد کی گمراہی سے بھی۔جَعَلَنَا اللهُ منْهُمْ\n- تاویل کے ایک معنی تو ہیں (کسی چیز کی اصل حقیقت) اس معنی کے اعتبار سےإِلا اللهُ پر وقف ضروری ہے۔ کیونکہ ہر چیز کی اصل حقیقت واضح طورپرصرف اللہ تعالیٰ ہی جانتا ہے۔ تاویل کے دوسرے معنی ہیں ”کسی چیزکی تفسیر وتعبیر اوربیان وتوضیح“ اس اعتبار سے الا اللہ پر وقف کے بجائے «وَالرَّاسِخُونَ فِي الْعِلْمِ» پر بھی وقف کیا جاسکتاہے کیونکہ مضبوط علم والے بھی صحیح تفسیر وتوضیح کا علم رکھتے ہیں۔ ”تاویل“ کے یہ دونوں معنی قرآن کریم کے استعمال سے ثابت ہیں۔ (ملخص ازابن کثیر)",
