      "arFull": "هُوَ الَّذِیْ یُصَوِّرُكُمْ فِی الْاَرْحَامِ كَیْفَ یَشَآءُ ؕ لَاۤ اِلٰهَ اِلَّا هُوَ الْعَزِیْزُ الْحَكِیْمُ ۟",
