      "arFull": "اِنَّ الَّذِیْنَ كَفَرُوْا لَنْ تُغْنِیَ عَنْهُمْ اَمْوَالُهُمْ وَلَاۤ اَوْلَادُهُمْ مِّنَ اللّٰهِ شَیْـًٔا ؕ وَاُولٰٓىِٕكَ هُمْ وَقُوْدُ النَّارِ ۟ۙ",
