      "arFull": "قُلْ اَؤُنَبِّئُكُمْ بِخَیْرٍ مِّنْ ذٰلِكُمْ ؕ لِلَّذِیْنَ اتَّقَوْا عِنْدَ رَبِّهِمْ جَنّٰتٌ تَجْرِیْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِیْنَ فِیْهَا وَاَزْوَاجٌ مُّطَهَّرَةٌ وَّرِضْوَانٌ مِّنَ اللّٰهِ ؕ وَاللّٰهُ بَصِیْرٌ بِالْعِبَادِ ۟ۚ",
      "ur": "آپ کہہ دیجئے! کیا میں تمہیں اس سے بہت ہی بہتر چیز بتاؤں؟ تقویٰ والوں کے لئے ان کے رب تعالیٰ کے پاس جنتیں ہیں جن کے نیچے نہریں بہہ رہی ہیں جن میں وه ہمیشہ رہیں گے[1] اور پاکیزه بیویاں[2] اور اللہ تعالیٰ کی رضامندی ہے، سب بندے اللہ تعالیٰ کی نگاه میں ہیں۔",
      "en": "Say, \"Shall I inform you of [something] better than that? For those who fear Allāh will be gardens in the presence of their Lord beneath which rivers flow, wherein they abide eternally, and purified spouses and approval from Allāh. And Allāh is Seeing [i.e., aware] of [His] servants -",
      "footnotesUr": "[1] اس آیت میں اہل ایمان کو بتلایا جا رہا ہے کہ دنیاکی مذکورہ چیزوں میں ہی مت کھو جانا، بلکہ ان سے بہتر تو وہ زندگی اور اس کی نعمتیں ہیں جو رب کے پاس ہیں، جن کے مستحق اہل تقویٰ ہی ہوں گے۔ اس لئے تم تقویٰ اختیار کرو۔ اگر یہ تمہارے اندر پیدا ہو گیا تو یقیناً تم دین ودنیاکی بھلائیاں اپنے دامن میں سمیٹ لو گے۔\n[2] پاکیزہ، یعنی وہ دنیاوی میل کچیل، حیض ونفاس اور دیگر آلودگیوں سے پاک ہوں گی اورپاک دامن ہونگی۔ اس سے اگلی دو آیات میں اہل تقویٰ کی صفات کا تذکرہ ہے۔",
