      "arFull": "شَهِدَ اللّٰهُ اَنَّهٗ لَاۤ اِلٰهَ اِلَّا هُوَ ۙ وَالْمَلٰٓىِٕكَةُ وَاُولُوا الْعِلْمِ قَآىِٕمًا بِالْقِسْطِ ؕ لَاۤ اِلٰهَ اِلَّا هُوَ الْعَزِیْزُ الْحَكِیْمُ ۟ؕ",
      "ur": "اللہ تعالیٰ، فرشتے اور اہل علم اس بات کی گواہی دیتے ہیں کہ اللہ کے سوا کوئی معبود نہیں[1] اور وه عدل کو قائم رکھنے واﻻ ہے، اس غالب اور حکمت والے کے سوا کوئی عبادت کے ﻻئق نہیں۔",
      "en": "Allāh witnesses that there is no deity except Him, and [so do] the angels and those of knowledge - [that He is] maintaining [creation] in justice. There is no deity except Him, the Exalted in Might, the Wise.",
      "footnotesUr": "[1] شہادت کے معنی بیان کرنے اور آگاہ کرنے کے ہیں،یعنی اللہ تعالیٰ نے جو کچھ پیدا کیا، اور بیان کیا، اس کے ذریعے سے اس نےاپنی وحدانیت کی طرف ہماری رہنمائی فرمائی۔ (فتح القدیر) فرشتے اوراہل علم بھی اس کی توحید کی گواہی دیتے ہیں۔ اس میں اہل علم کی بڑی فضیلت اور عظمت ہے کہ اللہ تعالیٰ نے اپنے اور فرشتوں کے ناموں کے ساتھ ان کا ذکر فرمایا ہے تاہم اس سے مراد صرف وہ اہل علم ہیں جو کتاب وسنت کے علم سے بہرہ ور ہیں۔ (فتح القدیر)",
      "footnotesEn": null,
