      "number": 21,
      "arFull": "اِنَّ الَّذِیْنَ یَكْفُرُوْنَ بِاٰیٰتِ اللّٰهِ وَیَقْتُلُوْنَ النَّبِیّٖنَ بِغَیْرِ حَقٍّ ۙ وَّیَقْتُلُوْنَ الَّذِیْنَ یَاْمُرُوْنَ بِالْقِسْطِ مِنَ النَّاسِ ۙ فَبَشِّرْهُمْ بِعَذَابٍ اَلِیْمٍ ۟",
      "ur": "جو لوگ اللہ تعالیٰ کی آیتوں سے کفر کرتے ہیں اورناحق نبیوں کو قتل کر ڈالتے ہیں اور جو لوگ عدل وانصاف کی بات کہیں انہیں بھی قتل کر ڈالتے ہیں[1] ، تو اے نبی! انہیں دردناک عذاب کی خبردے دیجئے۔",
      "en": "Those who disbelieve in the signs of Allāh and kill the prophets without right and kill those who order justice from among the people - give them tidings of a painful punishment.",
      "footnotesUr": "[1] یعنی ان کی سرکشی وبغاوت اس حد تک پہنچ چکی تھی کہ صرف نبیوں کو ہی انہوں نے ناحق قتل نہیں کیابلکہ ان تک کو بھی قتل کر ڈالاجو عدل وانصاف کی بات کرتے تھے۔ یعنی وہ مومنین مخلصین اور داعیان حق جو امر بالمعروف اورنہی عن المنکر کافریضہ انجام دیتے تھے۔ نبیوں کے ساتھ ان کا تذکرہ فرما کر اللہ تعالیٰ نے ان کی عظمت وفضیلت بھی واضح کردی۔",
