      "arFull": "اُولٰٓىِٕكَ الَّذِیْنَ حَبِطَتْ اَعْمَالُهُمْ فِی الدُّنْیَا وَالْاٰخِرَةِ ؗ وَمَا لَهُمْ مِّنْ نّٰصِرِیْنَ ۟",
