      "number": 26,
      "arFull": "قُلِ اللّٰهُمَّ مٰلِكَ الْمُلْكِ تُؤْتِی الْمُلْكَ مَنْ تَشَآءُ وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشَآءُ ؗ وَتُعِزُّ مَنْ تَشَآءُ وَتُذِلُّ مَنْ تَشَآءُ ؕ بِیَدِكَ الْخَیْرُ ؕ اِنَّكَ عَلٰی كُلِّ شَیْءٍ قَدِیْرٌ ۟",
      "ur": "آپ کہہ دیجئے اے اللہ! اے تمام جہان کے مالک! تو جسے چاہے بادشاہی دے اور جس سے چاہے سلطنت چھین لے اور تو جسے چاہے عزت دے اورجسے چاہے ذلت دے، تیرے ہی ہاتھ میں سب بھلائیاں ہیں[1] ، بے شک تو ہر چیز پر قادر ہے۔",
      "en": "Say, \"O Allāh, Owner of Sovereignty, You give sovereignty to whom You will and You take sovereignty away from whom You will. You honor whom You will and You humble whom You will. In Your hand[121] is [all] good. Indeed, You are over all things competent.",
      "footnotesUr": "[1] اس آیت میں اللہ تعالیٰ کی بے پناہ قوت وطاقت کا اظہار ہے، شاہ کو گدا بنا دے، گدا کو شاہ بنا دے، تمام اختیارات کا مالک وہی ہے الْخَيْرُ بِيَدِكَ کی بجائے بِيَدِكَ الْخَيْرُ (خبر کی تقدیم کے ساتھ) سے مقصود تخصیص ہے یعنی تمام بھلائیاں صرف تیرے ہی ہاتھ میں ہیں۔ تیرے سوا کوئی بھلائی دینے والا نہیں۔ ”شر“ کا خالق بھی اگرچہ اللہ تعالیٰ ہی ہے لیکن ذکر صرف خیر کا کیا گیا ہے، شر کا نہیں۔ اس لئے کہ خیر اللہ کا فضل محض ہے، بخلاف شر کے کہ یہ انسان کے اپنے عمل کا بدلہ ہے جو اسے پہنچتا ہے یا اس لئے کہ شر بھی اس کے قضا وقدر کا حصہ ہے جو خیر کو متضمن ہے، اس اعتبار سے اس کے تمام افعال خیر ہیں۔ فَأَفْعَالُهُ كُلُّهَا خَيْرٌ (فتح القدير)",
      "footnotesEn": "[121] See footnote to 2:19.",
