      "arFull": "قَالَ رَبِّ اَنّٰی یَكُوْنُ لِیْ غُلٰمٌ وَّقَدْ بَلَغَنِیَ الْكِبَرُ وَامْرَاَتِیْ عَاقِرٌ ؕ قَالَ كَذٰلِكَ اللّٰهُ یَفْعَلُ مَا یَشَآءُ ۟",
      "ur": "کہنے لگے اے میرے رب! میرے ہاں بچہ کیسے ہوگا؟ میں بالکل بوڑھا ہو گیا ہوں اور میری بیوی بانجھ ہے، فرمایا، اسی طرح اللہ تعالیٰ جو چاہے کرتا ہے۔",
