      "en": "And He will teach him writing and wisdom[126] and the Torah and the Gospel",
      "footnotesUr": "[1] كِتَابٌ سے مراد کتابت (لکھنا) ہے۔ جیسا کہ ترجمہ میں اختیار کیا گیا ہے یا انجیل وتورات کے علاوہ کوئی اور کتاب ہے جس کا علم اللہ تعالیٰ نے انہیں دیا (قرطبی) یاتورات وانجیل،الْكِتَابُ اورالْحِكْمَةُکی تفسیر ہے۔",
