      "arFull": "اِنَّ هٰذَا لَهُوَ الْقَصَصُ الْحَقُّ ۚ وَمَا مِنْ اِلٰهٍ اِلَّا اللّٰهُ ؕ وَاِنَّ اللّٰهَ لَهُوَ الْعَزِیْزُ الْحَكِیْمُ ۟",
      "ur": "یقیناً صرف یہی سچا بیان ہے اور کوئی معبود برحق نہیں بجز اللہ تعالیٰ کے اور بے شک غالب اور حکمت واﻻ اللہ تعالیٰ ہی ہے۔",
