      "number": 94,
      "arFull": "فَمَنِ افْتَرٰی عَلَی اللّٰهِ الْكَذِبَ مِنْ بَعْدِ ذٰلِكَ فَاُولٰٓىِٕكَ هُمُ الظّٰلِمُوْنَ ۟ؔ",
