      "arFull": "قُلْ یٰۤاَهْلَ الْكِتٰبِ لِمَ تَصُدُّوْنَ عَنْ سَبِیْلِ اللّٰهِ مَنْ اٰمَنَ تَبْغُوْنَهَا عِوَجًا وَّاَنْتُمْ شُهَدَآءُ ؕ وَمَا اللّٰهُ بِغَافِلٍ عَمَّا تَعْمَلُوْنَ ۟",
      "ur": "ان اہل کتاب سے کہو کہ تم اللہ تعالیٰ کی راه سے لوگوں کو کیوں روکتے ہو؟ اور اس میں عیب ٹٹولتے ہو، حاﻻنکہ تم خود شاہد ہو[1] ، اللہ تعالیٰ تمہارے اعمال سے بے خبر نہیں.",
