      "arFull": "وَسَارِعُوْۤا اِلٰی مَغْفِرَةٍ مِّنْ رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّمٰوٰتُ وَالْاَرْضُ ۙ اُعِدَّتْ لِلْمُتَّقِیْنَ ۟ۙ",
