      "arFull": "لَقَدْ سَمِعَ اللّٰهُ قَوْلَ الَّذِیْنَ قَالُوْۤا اِنَّ اللّٰهَ فَقِیْرٌ وَّنَحْنُ اَغْنِیَآءُ ۘ سَنَكْتُبُ مَا قَالُوْا وَقَتْلَهُمُ الْاَنْۢبِیَآءَ بِغَیْرِ حَقٍّ ۙ وَّنَقُوْلُ ذُوْقُوْا عَذَابَ الْحَرِیْقِ ۟",
      "ur": "یقیناً اللہ تعالیٰ نے ان لوگوں کا قول بھی سنا جنہوں نے کہا کہ اللہ تعالیٰ فقیر ہے اور ہم تونگر ہیں[1] ان کے اس قول کو ہم لکھ لیں گے۔ اور ان کا انبیا کو بلا وجہ قتل کرنا بھی[2]، اور ہم ان سے کہیں گے کہ جلنے واﻻ عذاب چکھو!",
      "en": "Allāh has certainly heard the statement of those [Jews] who said, \"Indeed, Allāh is poor, while we are rich.\" We will record what they said and their killing of the prophets without right and will say, \"Taste the punishment of the Burning Fire.",
      "footnotesUr": "[1] جب اللہ تعالیٰ نے اہل ایمان کو اللہ کی راہ میں خرچ کرنے کی ترغیب دی اور فرمایا «مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا»( البقرۃ: 245) ”کون ہے جو اللہ کو قرض حسن دے“، تو یہود نے کہا اے محمد ج! تیرا رب فقیر ہوگیا ہے کہ اپنے بندوں سے قرض مانگ رہا ہے؟ جس پر اللہ تعالیٰ نے یہ آیت نازل فرمائی (ابن کثیر)\n[2] یعنی مذکورہ قول جس میں اللہ کی شان میں گستاخی ہے اور اسی طرح ان کے (اسلاف) کا انبیاء ﻹ کو ناحق قتل کرنا، ان کے یہ سارے جرائم اللہ کی بارگاہ میں درج ہیں، جن پر وہ جہنم کی آگ میں داخل ہوں گے۔ٍ",
