      "arFull": "رَبَّنَاۤ اِنَّكَ مَنْ تُدْخِلِ النَّارَ فَقَدْ اَخْزَیْتَهٗ ؕ وَمَا لِلظّٰلِمِیْنَ مِنْ اَنْصَارٍ ۟",
      "ur": "اے ہمارے پالنے والے! تو جسے جہنم میں ڈالے یقیناً تو نے اسے رسوا کیا، اور ﻇالموں کا مددگار کوئی نہیں.",
