      "arFull": "لَا یَغُرَّنَّكَ تَقَلُّبُ الَّذِیْنَ كَفَرُوْا فِی الْبِلَادِ ۟ؕ",
      "ur": "تجھے کافروں کا شہروں میں چلنا پھرنا فریب میں نہ ڈال دے.[1]",
      "en": "Be not deceived by the [uninhibited] movement of the disbelievers throughout the land.",
      "footnotesUr": "[1] خطاب اگرچہ نبی (صلى الله عليه وسلم) سے ہے لیکن مخاطب پوری امت ہے شہر میں چلنے پھرنے سے مراد تجارت وکاروبار کے لئے ایک شہر سے دوسرے شہر یا ایک ملک سے دوسرے ملک جانا ہے۔ یہ تجارتی سفر وسائل دنیا کی فراوانی اور کاروبار کے وسعت وفروغ کی دلیل ہوتا ہے۔ اللہ تعالیٰ فرماتا ہے، یہ سب کچھ عارضی اور چند روزہ فائدہ ہے، اس سے اہل ایمان کو دھوکہ میں مبتلا نہیں ہو چاہئے، اصل انجام پر نظر رکھنی چاہئے، جو ایمان سے محرومی کی صورت میں جہنم کا دائمی عذاب ہے جس میں دولت دنیا سے مالا مال یہ کافر مبتلا ہوں گے۔ یہ مضمون اور بھی متعدد مقامات پر بیان کیا گیا ہے۔ مثلاً «مَا يُجَادِلُ فِي آيَاتِ اللَّهِ إِلا الَّذِينَ كَفَرُوا فَلا يَغْرُرْكَ تَقَلُّبُهُمْ فِي الْبِلادِ» ( سورۃ المومن: 4) ”اللہ کی آیتوں میں وہی لوگ جھگڑتے ہیں جو کافر ہیں، پس ان کا شہروں میں چلنا پھرنا آپ کو دھوکے میں نہ ڈالے“۔ «إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لا يُفْلِحُونَ، مَتَاعٌ فِي الدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ» (سورۂ یونس: 69-70) «نُمَتِّعُهُمْ قَلِيلا ثُمَّ نَضْطَرُّهُمْ إِلَى عَذَابٍ غَلِيظٍ» ( سورۂ لقمان:24)",
      "footnotesEn": null,
